use std::io::Write;
use std::path::PathBuf;
use std::process::{Command,Output,Stdio};
use std::sync::atomic::{AtomicU64,Ordering};
const BIN:&str=env!("CARGO_BIN_EXE_lfz");
static NEXT:AtomicU64=AtomicU64::new(0);
struct Work(PathBuf);
impl Work {
 fn new()->Self {let p=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("Temp/T20-tooling/cli-tests").join(format!("{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir_all(&p).unwrap();Self(p)}
 fn run(&self,args:&[&str],stdin:&[u8])->Output {let mut c=Command::new(BIN).args(args).current_dir(&self.0).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();if let Some(mut p)=c.stdin.take(){let _=p.write_all(stdin);}let end=std::time::Instant::now()+std::time::Duration::from_secs(10);while c.try_wait().unwrap().is_none(){if std::time::Instant::now()>=end{let _=c.kill();let _=c.wait();panic!("模块check进程超时");}std::thread::sleep(std::time::Duration::from_millis(5));}c.wait_with_output().unwrap()}
}
fn repl(w:&Work,input:&str)->Output{w.run(&["repl"],input.as_bytes())}
#[test]fn persistent_bindings_closure_and_side_effects_once(){let w=Work::new();let r=repl(&w,"var x=1\nfn get()=>x\nx=2\nget()\nprint(\"once\")\nget()\n:quit\nprint(\"never\")\n");assert_eq!(r.status.code(),Some(0),"{r:?}");let out=String::from_utf8(r.stdout).unwrap();assert_eq!(out.lines().filter(|l|*l=="once").count(),1);assert!(!out.contains("never"));assert_eq!(out.lines().filter(|l|*l=="2").count(),2);assert!(r.stderr.is_empty());}
#[test]fn multiline_eof_and_incomplete_errors_continue(){let w=Work::new();let r=repl(&w,"fn add(x) {\nreturn x+1\n}\nadd(2)");assert_eq!(r.status.code(),Some(0),"{r:?}");assert_eq!(r.stdout,b"3\n");let r=repl(&w,"let =\nprint(\"after\")\nfn missing() {\n");assert_eq!(r.status.code(),Some(2));assert_eq!(r.stdout,b"after\n");let err=String::from_utf8(r.stderr).unwrap();assert!(err.contains("<repl:1>")&&err.contains("<repl:3>"),"{err}");}
#[test]fn input_consumes_shared_stdin_data_including_meta_command(){let w=Work::new();let r=repl(&w,"input()\n:quit\nprint(\"continued\")\n:quit\n");assert_eq!(r.status.code(),Some(0),"{r:?}");assert_eq!(r.stdout,b":quit\ncontinued\n");assert!(r.stderr.is_empty());}
#[test]fn reset_preserves_failure_history_and_argv(){let w=Work::new();let r=w.run(&["repl","--","--json","hello"],b"argv()[0]\n:unknown\nvar x=1\n:reset\nargv()[1]\nx\n:quit\n");assert_eq!(r.status.code(),Some(2));let out=String::from_utf8(r.stdout).unwrap();assert!(out.contains("--json")&&out.contains("hello"));let err=String::from_utf8(r.stderr).unwrap();assert!(err.contains("repl: 未知命令")&&err.contains("未定义的名字 'x'"));}
#[test]fn usage_and_pipe_no_prompt(){let w=Work::new();for args in [vec!["repl","--json"],vec!["--json","repl"]]{let r=w.run(&args,b"");assert_eq!(r.status.code(),Some(2));assert!(r.stdout.is_empty());assert!(String::from_utf8_lossy(&r.stderr).contains("repl 不支持 --json"));}let r=w.run(&["repl","extra.lfz"],b"");assert_eq!(r.status.code(),Some(2));let r=repl(&w,"// comment\n\n1\n");assert_eq!(r.stdout,b"1\n");assert!(r.stderr.is_empty());assert_eq!(repl(&w,"").status.code(),Some(0));}
#[test]fn old_source_caret_and_per_cell_limits(){let w=Work::new();let r=repl(&w,"fn fail()=>1/0\nfail()\nprint(\"recovered\")\n");assert_eq!(r.status.code(),Some(2));assert_eq!(r.stdout,b"recovered\n");let err=String::from_utf8(r.stderr).unwrap();assert!(err.contains("<repl:1>")&&err.contains("<repl:2>"),"{err}");let r=w.run(&["repl","--max-steps","50"],b"while true {}\n1\n:quit\n");assert_eq!(r.status.code(),Some(2));assert!(String::from_utf8_lossy(&r.stdout).ends_with("1\n"));assert!(String::from_utf8_lossy(&r.stderr).contains("ExecutionLimitError"));}
#[test]fn raw_cell_cap_stops_before_tail_effect(){let w=Work::new();let mut input=" ".repeat(1048576);input.push_str("x\nprint(\"never\")\n");let r=repl(&w,&input);assert_eq!(r.status.code(),Some(2));assert!(r.stdout.is_empty());assert!(String::from_utf8_lossy(&r.stderr).contains("cell bytes"));}
